/**
 * @file bicycle_page_anima.c
 * @brief Central page transition / cache configuration for lv_pm.
 */
#include "bicycle_page_anima.h"

#include "lv_pm_anima.h"
#include "lv_pm_gpu_anima.h"
#include "lv_pm_port.h"

typedef struct {
    const void * anima_cb;
    uint32_t direction;
    uint32_t time_ms;
    bool cache_enable;
    bool top_bar_en;
    bool back_bar_en;
} bicycle_page_anima_row_t;

/*
 * Page transition table (edit here only).
 *
 * LiveMap / Menu: fade (opacity only). Do NOT use
 * lv_pm_gpu_rotate_slide_anima — full-page rotate+slide is too heavy on
 * this panel (jank with map canvas underneath).
 * Overlay pages may use GPU zoom. Boot still calls apply_silent() so the
 * empty shell does not animate under splash; map_will_appear restores this.
 */
static const bicycle_page_anima_row_t s_page_anima[BICYCLE_PM_ID_COUNT] = {
    [BICYCLE_PM_ID_MAP] = {
        .anima_cb = &lv_pm_fade_anima,
        .direction = 0,
        .time_ms = 220,
        .cache_enable = true,
        .top_bar_en = true,
        .back_bar_en = false,
    },
    [BICYCLE_PM_ID_USB_TRANSFER] = {
        .anima_cb = &lv_pm_gpu_zoom_anima,
        .direction = LV_PM_GPU_DIR_CENTER,
        .time_ms = 280,
        .cache_enable = false,
        .top_bar_en = false,
        .back_bar_en = false,
    },
    [BICYCLE_PM_ID_STARTUP] = {
        .anima_cb = &lv_pm_no_anima,
        .direction = 0,
        .time_ms = 0,
        .cache_enable = false,
        .top_bar_en = false,
        .back_bar_en = false,
    },
    [BICYCLE_PM_ID_MENU] = {
        /* ⚠ **两个方向都由本行决定**（用户 2026-09-26 晚："主界面进入菜单和菜单返回
         * 主界面，不加动画了"）：
         *   进 = 菜单 ENTER（`lv_pm_open_page_msg`）+ 主界面 EXIT 用的是"打开页的
         *        options"（`lv_pm_core.c` 里 `&open_page->open_options`）⇒ 也是本行；
         *   回 = 菜单 EXIT（`lv_pm_close_page_msg` 只让当前页播退出动画，底下的主界面
         *        直接露出来）⇒ 还是本行。
         * 所以这里换 `lv_pm_no_anima` + 0ms 就两个方向都瞬变，而且**不牵动主界面自己
         * 的过渡**（开机揭场、从 USB/工厂页回来仍走 `[BICYCLE_PM_ID_MAP]` 那行的淡入）。 */
        .anima_cb = &lv_pm_no_anima,
        .direction = 0,
        .time_ms = 0,
        .cache_enable = false,
        .top_bar_en = true,
        .back_bar_en = false,
    },
    [BICYCLE_PM_ID_FACTORY] = {
        .anima_cb = &lv_pm_gpu_zoom_anima,
        .direction = LV_PM_GPU_DIR_CENTER,
        .time_ms = 250,
        .cache_enable = false,
        .top_bar_en = false,
        .back_bar_en = false,
    },
};

/**
 * @brief 自行车 page anima apply。
 */
void bicycle_page_anima_apply(lv_pm_page_t page, bicycle_pm_id_t id)
{
    const bicycle_page_anima_row_t * row;

    if (page == NULL || id >= BICYCLE_PM_ID_COUNT) {
        return;
    }

    row = &s_page_anima[id];
    lv_pm_set_open_options(page, row->anima_cb, LV_PM_TARGET_NEW,
                           row->direction, row->time_ms);
    lv_pm_set_cache_enable(page, row->cache_enable);
    lv_pm_set_top_bar(page, row->top_bar_en);
    lv_pm_set_back_bar(page, row->back_bar_en);
}

/**
 * @brief 自行车 page anima apply silent。
 */
void bicycle_page_anima_apply_silent(lv_pm_page_t page)
{
    if (page == NULL) {
        return;
    }

    lv_pm_set_open_options(page, &lv_pm_no_anima, LV_PM_TARGET_NEW, 0, 0);
}
#include "../include/lv_pm_anima.h"

static void fade_exec(void * var, int32_t value)
{
    lv_obj_set_style_opa((lv_obj_t *)var, (lv_opa_t)value, 0);
}

static void _pm_fade_appear(lv_pm_anima_data * anima_data, lv_anim_t * appear_anima)
{
    lv_obj_t * page = anima_data->pm_page->page;
    lv_pm_open_options_t * open_options = &(anima_data->pm_page->open_options);

    lv_obj_remove_flag(page, LV_OBJ_FLAG_HIDDEN);
    lv_obj_set_style_opa(page, LV_OPA_TRANSP, 0);

    lv_anim_init(appear_anima);
    lv_anim_set_user_data(appear_anima, (void *)anima_data);
    lv_anim_set_var(appear_anima, page);
    lv_anim_set_values(appear_anima, 0, 255);
    lv_anim_set_time(appear_anima, open_options->time);
    lv_anim_set_repeat_count(appear_anima, 1);
    lv_anim_set_exec_cb(appear_anima, fade_exec);
    lv_anim_set_ready_cb(appear_anima, get_lv_pm_deleted_cb());
    lv_anim_set_path_cb(appear_anima, lv_anim_path_ease_out);
    lv_anim_start(appear_anima);
}

static void _pm_fade_dis_appear(lv_pm_anima_data * anima_data, lv_anim_t * dis_appear_anima)
{
    lv_obj_t * page = anima_data->pm_page->page;
    lv_pm_open_options_t * open_options = &(anima_data->pm_page->open_options);

    lv_obj_remove_flag(page, LV_OBJ_FLAG_HIDDEN);
    lv_obj_set_style_opa(page, LV_OPA_COVER, 0);

    lv_anim_init(dis_appear_anima);
    lv_anim_set_user_data(dis_appear_anima, (void *)anima_data);
    lv_anim_set_var(dis_appear_anima, page);
    lv_anim_set_values(dis_appear_anima, 255, 0);
    lv_anim_set_time(dis_appear_anima, open_options->time);
    lv_anim_set_repeat_count(dis_appear_anima, 1);
    lv_anim_set_exec_cb(dis_appear_anima, fade_exec);
    lv_anim_set_ready_cb(dis_appear_anima, get_lv_pm_deleted_cb());
    lv_anim_set_path_cb(dis_appear_anima, lv_anim_path_ease_in);
    lv_anim_start(dis_appear_anima);
}

const lv_pm_anima_t lv_pm_fade_anima =
{
    _pm_fade_appear,
    _pm_fade_dis_appear
};
#include "../include/lv_pm_anima.h"
#include "../include/lv_pm_bar.h"

static void _pm_popup_no_anima_appear(lv_pm_anima_data* anima_data, lv_anim_t* appear_anima)
{
    lv_pm_open_options_t* open_options = &(anima_data->pm_page->open_options);
    lv_obj_t* page = anima_data->pm_page->page;
    lv_coord_t rest_y = 0;

    // 设置动画控制变量，确保动画数据有效
    lv_anim_init(appear_anima);
    lv_anim_set_user_data(appear_anima, (void*)anima_data);
    lv_anim_set_var(appear_anima, page);

#if LV_PM_USE_STA_BAR
    if (anima_data->pm_page->flag.top_bar_en) {
        rest_y = lv_pm_status_bar_height();
    }
#endif

    // 直接设置控件到最终位置，模拟动画完成状态
    switch (open_options->direction)
    {
    case 0:
    case 1:
        lv_obj_set_y(page, rest_y);
        break;
    case 2:
    case 3:
        lv_obj_set_x(page, 0);
        break;
    default:
        break;
    }

    lv_obj_remove_flag(page, LV_OBJ_FLAG_HIDDEN);
    lv_obj_move_foreground(page);

    // 触发动画完成回调
    lv_anim_ready_cb_t ready_cb = get_lv_pm_deleted_cb();
    if (ready_cb) ready_cb(appear_anima);
}

static void _pm_popup_no_anima_dis_appear(lv_pm_anima_data* anima_data, lv_anim_t* dis_appear_anima)
{
    lv_obj_t* page = anima_data->pm_page->page;

    lv_anim_init(dis_appear_anima);
    lv_anim_set_user_data(dis_appear_anima, (void*)anima_data);
    lv_anim_set_var(dis_appear_anima, page);

    // 直接隐藏页面，模拟动画完成状态
    lv_obj_add_flag(page, LV_OBJ_FLAG_HIDDEN);

    // 触发动画完成回调
    lv_anim_ready_cb_t ready_cb = get_lv_pm_deleted_cb();
    if (ready_cb) ready_cb(dis_appear_anima);
}

const lv_pm_anima_t lv_pm_no_anima =
{
    _pm_popup_no_anima_appear,
    _pm_popup_no_anima_dis_appear
};
